/* Files are parsed in the visitor's browser. Nothing is uploaded by this module. */
const FILE_LIMIT=20*1024*1024;
function setImportProgress(message){const el=document.querySelector('#masterImportStatus');if(el&&message)el.textContent=message}
async function readApiJson(response){const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('当前托管环境没有文件解析接口');const data=await response.json();if(!response.ok)throw new Error(data.error||'读取失败');return data}
async function tryLocalParser(file,name=file.name){if(!['localhost','127.0.0.1'].includes(location.hostname))return null;const response=await fetch('/api/import-resume',{method:'POST',headers:{'x-filename':encodeURIComponent(name),'content-type':'application/octet-stream'},body:file});return(await readApiJson(response)).text}
async function ocrImage(source,label='图片'){if(!window.Tesseract)throw new Error('图片识别组件加载失败，请检查网络后重试');const result=await Tesseract.recognize(source,'chi_sim+eng',{logger:m=>{if(m.status==='recognizing text')setImportProgress(`${label}识别中 ${Math.round((m.progress||0)*100)}%`)}});return result.data.text.trim()}
async function parsePdf(file){if(!window.pdfjsLib)throw new Error('PDF 读取组件加载失败，请检查网络后重试');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise,parts=[];for(let i=1;i<=pdf.numPages;i++){setImportProgress(`正在读取 PDF 第 ${i}/${pdf.numPages} 页…`);const page=await pdf.getPage(i),content=await page.getTextContent();let value=content.items.map(x=>x.str).join(' ').replace(/\s+/g,' ').trim();if(value.length<25){const viewport=page.getViewport({scale:1.7}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;value=await ocrImage(canvas,`PDF 第 ${i} 页`)}if(value)parts.push(value)}if(!parts.length)throw new Error('PDF 中没有识别到文字，请尝试上传清晰图片');return parts.join('\n\n')}
async function parseDocx(file){if(!window.mammoth)throw new Error('DOCX 读取组件加载失败，请检查网络后重试');const result=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});if(!result.value.trim())throw new Error('DOCX 中没有读取到文字');return result.value.trim()}
async function extractUploadedFile(file,options={}){if(file.size>FILE_LIMIT)throw new Error('单个文件不能超过 20MB');const local=await tryLocalParser(file,options.serverName||file.name).catch(()=>null);if(local)return local;const ext=(file.name.split('.').pop()||'').toLowerCase();if(ext==='txt')return(await file.text()).trim();if(ext==='pdf')return parsePdf(file);if(ext==='docx')return parseDocx(file);if(['png','jpg','jpeg','webp'].includes(ext)||file.type.startsWith('image/'))return ocrImage(file,options.label||'图片');throw new Error('仅支持 PDF、DOCX、TXT、PNG、JPG 和 WEBP')}
window.extractUploadedFile=extractUploadedFile;
